function IconBox({ children, tone = 'cyan' }: { children: React.ReactNode; tone?: 'cyan' | 'dark' | 'red' }) {
  return <span className={`inline-flex h-8 w-8 items-center justify-center border ${tone === 'dark' ? 'border-[#296b71] bg-[#07383d] text-[#92e6ec]' : tone === 'red' ? 'border-[#d89b9b] bg-[#f6dfdf] text-[#8e2929]' : 'border-[#92e6ec] bg-[#c6fcff] text-[#0f4c52]'}`}>{children}</span>;
}

function TopNav({ role }: { role: Role }) {
  const [location] = useLocation();
  const meta = roleMeta[role];
  return <header className="topnav">
    <div className="topnav-inner">
      <Link href={meta.home} className="flex shrink-0 items-center gap-3" data-testid="link-brand">
        <span className="flex h-8 w-8 items-center justify-center border border-[#92e6ec] text-[#c6fcff]"><Terminal size={16} /></span>
        <span className="font-display text-[17px] font-bold tracking-[-.03em]">SDMS<span className="text-[#92e6ec]">/</span></span>
      </Link>
      <div className="hidden h-7 w-px bg-[#296b71] md:block" />
      <nav className="flex min-w-0 flex-1 items-center gap-5">
        {meta.links.map((link) => <Link key={link.href} href={link.href} className={`topnav-link ${location === link.href || (link.href.includes('/new') && location.includes('/distributions/')) ? 'active' : ''}`} data-testid={`link-nav-${link.label.toLowerCase().replaceAll(' ', '-')}`}>{link.label}</Link>)}
      </nav>
      <div className="hidden items-center gap-3 border-l border-[#296b71] pl-5 sm:flex">
        <span className="font-mono text-[10px] tracking-[.12em] text-[#92e6ec]">NODE 01 / PRIVATE</span>
        <span className="h-2 w-2 bg-[#92e6ec]" />
      </div>
      <Link href="/login/authority" className="hidden text-[#b9d8da] sm:block" data-testid="link-switch-role"><UserRound size={16} /></Link>
    </div>
  </header>;
}

function ContextBar({ role, section, detail }: { role: Role; section: string; detail?: string }) {
  return <div className="border-b border-[#b7ced0] bg-[#eaf4f5]">
    <div className="mx-auto flex max-w-[1480px] items-center justify-between px-[clamp(16px,4vw,58px)] py-2.5">
      <div className="flex min-w-0 items-center gap-2 text-[11px] uppercase tracking-[.12em] text-[#587579]"><span className="font-mono text-[#0f4c52]">{roleMeta[role].label}</span><ChevronRight size={13} /><span className="truncate">{section}</span>{detail && <><ChevronRight size={13} /><span className="truncate text-[#0f4c52]">{detail}</span></>}</div>
      <div className="hidden gap-4 font-mono text-[10px] text-[#587579] sm:flex"><span>ENV / SIMULATION</span><span>UTC+05:30</span></div>
    </div>
  </div>;
}

function Shell({ role, section, detail, children }: { role: Role; section: string; detail?: string; children: React.ReactNode }) {
  return <div className="sdms-shell"><TopNav role={role} /><ContextBar role={role} section={section} detail={detail} /><main className="sdms-main">{children}</main></div>;
}

function PageHeader({ eyebrow, title, description, actions }: { eyebrow: string; title: string; description?: string; actions?: React.ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-5 border-b border-[#b7ced0] pb-6 md:flex-row md:items-end"><div><div className="eyebrow mb-3">{eyebrow}</div><h1 className="title-display">{title}</h1>{description && <p className="mt-3 max-w-2xl text-[13px] leading-6 text-[#587579]">{description}</p>}</div>{actions && <div className="flex shrink-0 flex-wrap gap-2">{actions}</div>}</div>;
}

function MetricStrip({ items }: { items: { label: string; value: string; note?: string }[] }) {
  return <div className="metric-strip mb-7">{items.map((item) => <div className="metric-cell" key={item.label}><div className="eyebrow">{item.label}</div><div className="metric-value" data-testid={`metric-${item.label.toLowerCase().replaceAll(' ', '-')}`}>{item.value}</div>{item.note && <div className="mt-2 text-[11px] text-[#587579]">{item.note}</div>}</div>)}</div>;
}

function SectionLabel({ children, right }: { children: React.ReactNode; right?: React.ReactNode }) {
  return <div className="mb-3 flex items-center justify-between"><span className="eyebrow">{children}</span>{right}</div>;
}

function HashDisplay({ label, value }: { label: string; value: string }) {
  const [copied, setCopied] = useState(false);
  return <button onClick={() => { void navigator.clipboard?.writeText(value); setCopied(true); setTimeout(() => setCopied(false), 1200); }} className="group flex w-full items-center justify-between gap-3 border border-[#b7ced0] bg-[#f1f8f8] px-3 py-2 text-left" data-testid={`button-copy-${label.toLowerCase().replaceAll(' ', '-')}`}>
    <span><span className="eyebrow block mb-1">{label}</span><span className="font-mono text-[11px] text-[#0f4c52]">{value}</span></span><Copy size={14} className="text-[#587579] group-hover:text-[#0f4c52]" />{copied && <span className="font-mono text-[9px] text-[#0f4c52]">COPIED</span>}
  </button>;
}

function StatusRow({ label, value, state = 'verified', detail }: { label: string; value: string; state?: 'verified' | 'pending' | 'failure'; detail?: string }) {
  return <div className="flex items-center gap-3 border-b border-[#b7ced0] py-3"><span className={`h-2 w-2 shrink-0 ${state === 'failure' ? 'bg-[#a83d3d]' : state === 'pending' ? 'bg-[#d08a36]' : 'bg-[#49a6ae]'}`} /><span className="min-w-0 flex-1"><span className="block text-[12px] font-semibold uppercase tracking-[.04em] text-[#102f33]">{label}</span>{detail && <span className="mt-0.5 block text-[11px] text-[#587579]">{detail}</span>}</span><span className={`font-mono text-[11px] ${state === 'failure' ? 'text-[#8e2929]' : 'text-[#0f4c52]'}`}>{value}</span></div>;
}

function DocumentRegister({ docs: list = docs, action }: { docs?: Doc[]; action?: (doc: Doc) => React.ReactNode }) {
  return <div className="surface overflow-hidden"><div className="grid grid-cols-[1fr_1.2fr_.8fr_110px] border-b border-[#b7ced0] bg-[#f1f8f8] px-4 py-3 text-[10px] font-bold uppercase tracking-[.12em] text-[#587579] max-md:grid-cols-[1fr_.8fr_90px]"><span>Document register</span><span>File reference</span><span>Classification</span><span className="text-right max-md:hidden">Access</span></div>{list.map((doc) => <div className="data-row grid grid-cols-[1fr_1.2fr_.8fr_110px] items-center gap-3 px-4 py-4 max-md:grid-cols-[1fr_.8fr_90px]" key={doc.id} data-testid={`row-document-${doc.id}`}><div className="flex min-w-0 items-center gap-3"><IconBox><FileText size={15} /></IconBox><span className="min-w-0"><span className="block truncate text-[13px] font-bold text-[#0f4c52]">{doc.title}</span><span className="font-mono text-[10px] text-[#587579]">{doc.id}</span></span></div><span className="truncate font-mono text-[11px] text-[#587579]">{doc.file}</span><span className="font-mono text-[10px] text-[#0f4c52]">{doc.classification}</span><span className="text-right">{action ? action(doc) : <span className="font-mono text-[10px] text-[#587579]">REGISTERED</span>}</span></div>)}</div>;
}

function Dashboard({ role }: { role: Role }) {
  const meta = roleMeta[role];
  const isInvestigator = role === 'investigator';
  return <Shell role={role} section="Operations overview"><PageHeader eyebrow={`${meta.label} / LIVE VIEW`} title={role === 'admin' ? 'Security operations' : role === 'investigator' ? 'Forensic operations' : role === 'recipient' ? 'Authorized document access' : 'Release authority'} description={role === 'investigator' ? 'Trace a leaked artifact back through its document, recipient, session, watermark, signature, and ledger provenance.' : 'Precision control surface for institutional document movement. All values below are deterministic simulation data.'} actions={<Link href={role === 'investigator' ? '/investigator/investigations/new' : role === 'authority' ? '/authority/distributions/new' : role === 'admin' ? '/admin/events' : '/recipient/documents'} className="btn-primary flex items-center gap-2" data-testid="button-primary-action">{isInvestigator ? <ScanSearch size={15} /> : role === 'authority' ? <FileArchive size={15} /> : <ArrowRight size={15} />} {isInvestigator ? 'Start investigation' : role === 'authority' ? 'New release' : role === 'admin' ? 'Review events' : 'Open register'}</Link>} />
    <MetricStrip items={role === 'authority' ? [{ label: 'Documents', value: '03', note: 'registered artifacts' }, { label: 'Active releases', value: releaseCreated ? '04' : '03', note: 'private ledger bound' }, { label: 'Recipients', value: '03', note: 'authorized identities' }, { label: 'Release state', value: releaseCreated ? 'READY' : 'STAGED', note: 'simulation mode' }] : role === 'recipient' ? [{ label: 'Authorized', value: '03', note: 'documents in scope' }, { label: 'Unread', value: '01', note: 'requires review' }, { label: 'Last access', value: '14:32', note: '26 Sep 2026' }, { label: 'Identity', value: 'VALID', note: 'ML-DSA bound' }] : role === 'admin' ? [{ label: 'Events', value: '184', note: 'ledger entries' }, { label: 'Chain state', value: ledgerTampered ? 'ALERT' : 'INTACT', note: ledgerTampered ? 'repair required' : 'block 000 → 185' }, { label: 'PQC identities', value: '03', note: 'operational' }, { label: 'Node health', value: '99.98%', note: 'private network' }] : [{ label: 'Open cases', value: '01', note: 'priority review' }, { label: 'Matched events', value: '01', note: 'confidence 98.7%' }, { label: 'Evidence items', value: '04', note: 'chain-linked' }, { label: 'Desk state', value: 'READY', note: 'air-gapped mode' }]} />
    {role === 'investigator' ? <InvestigatorOverview /> : role === 'admin' ? <AdminOverview /> : <div className="grid gap-7 lg:grid-cols-[1.35fr_.65fr]"><div><SectionLabel right={<Link href={role === 'recipient' ? '/recipient/documents' : '/authority/documents'} className="font-mono text-[10px] text-[#0f4c52]" data-testid="link-view-register">VIEW REGISTER <ArrowRight className="ml-1 inline" size={12} /></Link>}>CURRENT REGISTER</SectionLabel><DocumentRegister action={role === 'recipient' ? (doc) => <Link href={`/recipient/documents/${doc.id}`} className="font-mono text-[10px] text-[#0f4c52] underline" data-testid={`link-open-${doc.id}`}>OPEN</Link> : undefined} /></div><div><SectionLabel>CONTROL NOTES</SectionLabel><div className="surface divide-y divide-[#b7ced0]">{[['01','Encryption profile','AES-256-GCM / ML-KEM'],['02','Release channel','AIR-GAPPED'],['03','Attribution','WATERMARK + LEDGER']].map(([n,k,v]) => <div className="flex items-start gap-3 p-4" key={n}><span className="font-mono text-[10px] text-[#49a6ae]">{n}</span><span><span className="block text-[12px] font-semibold">{k}</span><span className="font-mono text-[10px] text-[#587579]">{v}</span></span></div>)}</div></div></div>}
  </Shell>;
}

function InvestigatorOverview() {
  return <div className="grid gap-7 lg:grid-cols-[1.4fr_.6fr]"><div className="surface p-5"><SectionLabel right={<span className="font-mono text-[10px] text-[#49a6ae]">CASE / INV-2026-009</span>}>ACTIVE FORENSIC CASE</SectionLabel><div className="border border-[#92e6ec] bg-[#f1f8f8] p-5"><div className="eyebrow mb-4 text-[#0f4c52]">MATCH CONFIDENCE / 98.7%</div><h2 className="font-display text-3xl font-semibold tracking-[-.04em] text-[#0f4c52]">DECRYPTION EVENT<br />MATCHED</h2><div className="mt-6 flex items-center gap-2 text-[11px] text-[#587579]"><span className="h-2 w-2 bg-[#49a6ae]" /> DOC-2026-001 <ChevronRight size={12} /> REC-003 <ChevronRight size={12} /> {eventId}</div><Link href="/investigator/investigations/INV-2026-009" className="btn-secondary mt-6 inline-flex items-center gap-2" data-testid="link-active-case">Open analysis <ArrowRight size={14} /></Link></div></div><div className="surface p-5"><SectionLabel>CASE SIGNALS</SectionLabel><StatusRow label="Watermark" value="MATCH" /><StatusRow label="Signature" value="VALID" /><StatusRow label="Document hash" value="MATCH" /><StatusRow label="Ledger" value="INTACT" /></div></div>;
}

function AdminOverview() {
  return <div className="grid gap-7 lg:grid-cols-[1fr_1fr]"><div><SectionLabel right={<Link href="/admin/ledger" className="font-mono text-[10px] text-[#0f4c52]" data-testid="link-ledger">OPEN LEDGER <ArrowRight className="ml-1 inline" size={12} /></Link>}>LATEST LEDGER ACTIVITY</SectionLabel><LedgerTable compact /></div><div><SectionLabel>NODE OBSERVATIONS</SectionLabel><div className="surface p-4"><StatusRow label="Private ledger chain" value={ledgerTampered ? 'MISMATCH' : 'INTACT'} state={ledgerTampered ? 'failure' : 'verified'} detail="Block 184 / 185 continuity check" /><StatusRow label="PQC key service" value="ONLINE" detail="ML-KEM + ML-DSA key material" /><StatusRow label="Air-gapped relay" value="SEALED" detail="No external egress detected" /><StatusRow label="Audit recorder" value="RECORDING" detail="Last event DEC-000184" /></div></div></div>;
}

function AuthorityDocuments() { return <Shell role="authority" section="Documents"><PageHeader eyebrow="AUTHORITY / DOCUMENT REGISTER" title="Document register" description="Institutional documents available for controlled release. Open a record to inspect its immutable file reference." actions={<Link href="/authority/distributions/new" className="btn-primary flex items-center gap-2" data-testid="button-new-release"><FileArchive size={15} /> New release</Link>} /><DocumentRegister /></Shell>; }
function RecipientDocuments() { return <Shell role="recipient" section="Documents"><PageHeader eyebrow="RECIPIENT / AUTHORIZED REGISTER" title="Authorized documents" description="Only documents addressed to your identity appear in this register. Secure access requires staged local decryption." /><DocumentRegister action={(doc) => <Link href={`/recipient/documents/${doc.id}`} className="btn-quiet inline-flex items-center gap-1 !px-2 !py-1.5" data-testid={`button-open-document-${doc.id}`}>Open <ArrowRight size={12} /></Link>} /></Shell>; }

function StepIndicator({ step }: { step: number }) {
  return <div className="mb-8 flex items-center"><div className={`flex items-center gap-2 text-[11px] font-bold uppercase tracking-[.1em] ${step >= 1 ? 'text-[#0f4c52]' : 'text-[#587579]'}`}><span className="flex h-7 w-7 items-center justify-center border border-[#49a6ae] bg-[#c6fcff] font-mono">01</span> Payload</div><div className="mx-3 h-px w-12 bg-[#92e6ec] sm:mx-5 sm:w-20" /><div className={`flex items-center gap-2 text-[11px] font-bold uppercase tracking-[.1em] ${step >= 2 ? 'text-[#0f4c52]' : 'text-[#587579]'}`}><span className={`flex h-7 w-7 items-center justify-center border ${step >= 2 ? 'border-[#49a6ae] bg-[#c6fcff]' : 'border-[#b7ced0]'}`}>02</span> Recipients</div><div className="mx-3 h-px w-12 bg-[#92e6ec] sm:mx-5 sm:w-20" /><div className={`flex items-center gap-2 text-[11px] font-bold uppercase tracking-[.1em] ${step >= 3 ? 'text-[#0f4c52]' : 'text-[#587579]'}`}><span className={`flex h-7 w-7 items-center justify-center border ${step >= 3 ? 'border-[#49a6ae] bg-[#c6fcff]' : 'border-[#b7ced0]'}`}>03</span> Release</div></div>;
}

function NewDistribution() {
  const [step, setStep] = useState(1);
  const [selected, setSelected] = useState<string[]>(recipients.map((r) => r.id));
  const [released, setReleased] = useState(false);
  const toggle = (id: string) => setSelected((s) => s.includes(id) ? s.filter((x) => x !== id) : [...s, id]);
  if (released) return <Shell role="authority" section="Distributions" detail="REL-2026-004"><PageHeader eyebrow="AUTHORITY / RELEASE COMPLETE" title="Distribution released" description="The payload has been sealed, attributed, and written to the private ledger simulation." actions={<Link href="/authority/distributions/REL-2026-004" className="btn-primary flex items-center gap-2" data-testid="button-open-distribution">Open distribution <ArrowRight size={15} /></Link>} /><div className="surface p-6"><div className="flex items-center gap-3 border-b border-[#b7ced0] pb-5"><IconBox><Check size={17} /></IconBox><div><div className="font-display text-xl font-semibold text-[#0f4c52]">RELEASE ACCEPTED</div><div className="font-mono text-[11px] text-[#587579]">REL-2026-004 / written 26 SEP 2026 14:32:08 UTC</div></div></div><div className="mt-6 grid gap-4 sm:grid-cols-3"><HashDisplay label="Event ID" value={eventId} /><HashDisplay label="Ledger block" value="184" /><HashDisplay label="Recipients" value="REC-003 · REC-004 · REC-005" /></div></div></Shell>;
  return <Shell role="authority" section="Distributions" detail="NEW RELEASE"><PageHeader eyebrow="AUTHORITY / CONTROLLED RELEASE" title="New distribution" description="Prepare an encrypted, recipient-bound release. Nothing leaves the air-gapped simulation until the final release instruction." /><StepIndicator step={step} /><div className="grid gap-7 lg:grid-cols-[1.2fr_.8fr]"><div className="surface p-5 sm:p-7">{step === 1 && <><SectionLabel>01 / SELECT PAYLOAD</SectionLabel><div className="border-2 border-dashed border-[#92e6ec] bg-[#f1f8f8] p-7 text-center"><IconBox><FileText size={16} /></IconBox><div className="mt-4 font-display text-xl font-semibold text-[#0f4c52]">Select registered document</div><select className="mt-4 w-full border border-[#b7ced0] bg-[#eaf4f5] px-3 py-3 text-[12px] text-[#0f4c52]" data-testid="select-document"><option>DOC-2026-001 — Strategic Operations Report</option><option>DOC-2026-002 — Infrastructure Security Brief</option><option>DOC-2026-003 — Mission Logistics Report</option></select></div></>}{step === 2 && <><SectionLabel>02 / AUTHORIZE RECIPIENTS</SectionLabel><div className="divide-y divide-[#b7ced0] border border-[#b7ced0]">{recipients.map((r) => <label className="flex cursor-pointer items-center gap-4 p-4 hover:bg-[#f1f8f8]" key={r.id}><input type="checkbox" checked={selected.includes(r.id)} onChange={() => toggle(r.id)} className="h-4 w-4 accent-[#0f4c52]" data-testid={`checkbox-recipient-${r.id}`} /><span className="flex-1"><span className="block text-[13px] font-bold text-[#0f4c52]">{r.name}</span><span className="font-mono text-[10px] text-[#587579]">{r.id} / ML-DSA IDENTITY VALID</span></span><span className="font-mono text-[10px] text-[#0f4c52]">{selected.includes(r.id) ? 'SELECTED' : 'AVAILABLE'}</span></label>)}</div></>}{step === 3 && <><SectionLabel>03 / REVIEW AND RELEASE</SectionLabel><div className="space-y-0 border border-[#b7ced0] bg-[#f1f8f8] p-4"><StatusRow label="Payload" value="DOC-2026-001" detail="Strategic Operations Report / RESTRICTED" /><StatusRow label="Encryption" value="AES-256-GCM" detail="Content encryption key sealed with ML-KEM" /><StatusRow label="Identity" value="ML-DSA" detail="Authority signature required at release" /><StatusRow label="Transport" value="AIR-GAPPED" detail="Local relay only / no external services" /><StatusRow label="Audit" value="PRIVATE LEDGER" detail="Event will be written as block 184" /></div><div className="mt-5 border-l-2 border-[#49a6ae] pl-4 text-[12px] leading-5 text-[#587579]">Three recipients selected. Release creates a deterministic forensic attribution path for later investigation.</div></>}</div><div className="space-y-5"><div className="surface p-5"><SectionLabel>RELEASE MANIFEST</SectionLabel><div className="space-y-3 text-[12px]"><div className="flex justify-between border-b border-[#b7ced0] pb-3"><span className="text-[#587579]">Recipients</span><span className="font-mono text-[#0f4c52]">{selected.length.toString().padStart(2, '0')} / 03</span></div><div className="flex justify-between border-b border-[#b7ced0] pb-3"><span className="text-[#587579]">Clearance</span><span className="font-mono text-[#0f4c52]">RESTRICTED</span></div><div className="flex justify-between"><span className="text-[#587579]">Manifest</span><span className="font-mono text-[#0f4c52]">READY</span></div></div></div><div className="flex justify-between gap-3">{step > 1 ? <button className="btn-quiet flex items-center gap-2" onClick={() => setStep(step - 1)} data-testid="button-previous"><ArrowLeft size={14} /> Previous</button> : <span />}{step < 3 ? <button className="btn-primary flex items-center gap-2" disabled={step === 2 && selected.length === 0} onClick={() => setStep(step + 1)} data-testid="button-continue">Continue <ArrowRight size={14} /></button> : <button className="btn-primary flex items-center gap-2" onClick={() => { releaseCreated = true; setReleased(true); }} data-testid="button-release"><LockKeyhole size={14} /> Release securely</button>}</div></div></div></Shell>;
}

function DistributionRecord() { return <Shell role="authority" section="Distributions" detail="REL-2026-004"><PageHeader eyebrow="AUTHORITY / DISTRIBUTION RECORD" title="Strategic Operations Report" description="Immutable release record for a recipient-bound restricted payload." actions={<Link href="/authority/distributions/new" className="btn-quiet flex items-center gap-2" data-testid="button-new-followup"><FileArchive size={14} /> New release</Link>} /><div className="grid gap-7 lg:grid-cols-[1.15fr_.85fr]"><div className="space-y-7"><div className="surface p-5"><SectionLabel>RELEASE RECORD</SectionLabel><div className="grid gap-4 sm:grid-cols-2"><HashDisplay label="Distribution" value="REL-2026-004" /><HashDisplay label="Document" value="DOC-2026-001" /><HashDisplay label="Released" value="26 SEP 2026 14:32:08" /><HashDisplay label="Ledger block" value="184 / INTACT" /></div></div><div className="surface p-5"><SectionLabel>RECIPIENT ACKNOWLEDGEMENT</SectionLabel>{recipients.map((r) => <StatusRow key={r.id} label={r.name} value="SEALED" detail={`${r.id} / ML-DSA public identity bound`} />)}</div></div><div className="surface-deep p-5"><SectionLabel>CRYPTOGRAPHIC PROFILE</SectionLabel>{['AES-256-GCM content encryption','ML-KEM key encapsulation','ML-DSA authority signature','AIR-GAPPED relay','PRIVATE LEDGER audit'].map((x) => <div className="flex items-center gap-3 border-b border-[#296b71] py-3 text-[12px]" key={x}><Check size={14} className="text-[#92e6ec]" />{x}</div>)}<div className="mt-6"><HashDisplay label="Watermark seed" value={watermark} /></div></div></div></Shell>; }

function AuthorityHistory() { return <Shell role="authority" section="History"><PageHeader eyebrow="AUTHORITY / AUDIT HISTORY" title="Release history" description="Chronological release instructions and immutable event references." /><div className="surface overflow-hidden">{[['REL-2026-004','Strategic Operations Report','03 recipients','14:32:08','RELEASED'],['REL-2026-003','Infrastructure Security Brief','02 recipients','11:08:41','RELEASED'],['REL-2026-002','Mission Logistics Report','01 recipient','09:17:22','ARCHIVED']].map((row) => <div className="data-row grid grid-cols-[1fr_1.4fr_1fr_1fr_100px] gap-4 px-5 py-4 text-[12px] max-md:grid-cols-[1fr_1fr_100px]" key={row[0]}>{row.map((v,i) => <span className={`${i === 0 ? 'font-mono text-[#0f4c52]' : i === 4 ? 'text-right font-mono text-[10px]' : 'text-[#587579]'} ${i === 1 ? 'font-semibold text-[#0f4c52]' : ''} ${i === 2 || i === 3 ? 'max-md:hidden' : ''}`} key={v}>{v}</span>)}</div>)}</div></Shell>; }

function RecipientDocument() { const { id = 'DOC-2026-001' } = useParams<{ id: string }>(); const doc = docs.find((d) => d.id === id) ?? docs[0]; return <Shell role="recipient" section="Documents" detail={doc.id}><PageHeader eyebrow="RECIPIENT / DOCUMENT RECORD" title={doc.title} description="This record is encrypted for REC-003. The source file remains sealed until the local staged decryption completes." actions={<Link href={`/recipient/decrypt/${doc.id}`} className="btn-primary flex items-center gap-2" data-testid="button-start-decryption"><KeyRound size={15} /> Start decryption</Link>} /><div className="grid gap-7 lg:grid-cols-[1fr_.8fr]"><div className="forensic-sheet min-h-[350px] p-8"><div className="relative z-10"><div className="eyebrow">DOCUMENT ENVELOPE / SEALED</div><FileText className="mt-12 text-[#49a6ae]" size={36} /><h2 className="mt-5 max-w-md font-display text-3xl font-semibold tracking-[-.04em] text-[#0f4c52]">{doc.title}</h2><p className="mt-3 font-mono text-[11px] text-[#587579]">{doc.file}</p><div className="mt-12 grid max-w-lg gap-4 sm:grid-cols-2"><HashDisplay label="Document ID" value={doc.id} /><HashDisplay label="Recipient" value="REC-003 / ANANYA SHARMA" /></div></div></div><div className="surface p-5"><SectionLabel>ACCESS REQUIREMENTS</SectionLabel><StatusRow label="Identity" value="VALID" detail="REC-003 / ML-DSA public key available" /><StatusRow label="Envelope" value="SEALED" detail="ML-KEM encapsulated key" /><StatusRow label="Content" value="ENCRYPTED" detail="AES-256-GCM" /><StatusRow label="Air-gap" value="REQUIRED" detail="Local decryption worker" /><div className="mt-6 border-t border-[#b7ced0] pt-5"><HashDisplay label="Session prepared" value={`${sessionId} / READY`} /></div></div></div></Shell>; }

function DecryptPage() { const [stage, setStage] = useState(0); const { id = 'DOC-2026-001' } = useParams<{ id: string }>(); const stages = ['Identity attestation','ML-KEM key decapsulation','AES-256-GCM content verification','Watermark binding']; const run = () => { let n = 0; const timer = setInterval(() => { n += 1; setStage(n); if (n === stages.length) clearInterval(timer); }, 650); }; return <Shell role="recipient" section="Decrypt" detail={id}><PageHeader eyebrow="RECIPIENT / AIR-GAPPED WORKER" title="Staged secure decryption" description="A local simulation of the recipient-side release protocol. No plaintext or cryptographic material leaves this browser." actions={stage === stages.length ? <Link href={`/recipient/documents/${id}`} className="btn-secondary flex items-center gap-2" data-testid="button-return-document"><Check size={15} /> Document unlocked</Link> : <button className="btn-primary flex items-center gap-2" onClick={run} disabled={stage > 0} data-testid="button-run-decryption"><Play size={14} /> {stage ? 'Processing' : 'Run local worker'}</button>} /><div className="grid gap-7 lg:grid-cols-[.85fr_1.15fr]"><div className="surface p-5"><SectionLabel>PAYLOAD UNDER TEST</SectionLabel><div className="border border-[#b7ced0] bg-[#f1f8f8] p-5"><FileText className="text-[#49a6ae]" /><div className="mt-5 font-display text-xl font-semibold text-[#0f4c52]">Strategic Operations Report</div><div className="mt-2 font-mono text-[10px] text-[#587579]">DOC-2026-001 / RESTRICTED</div></div><div className="mt-5"><HashDisplay label="Worker session" value={`${sessionId} / LOCAL`} /></div></div><div className="surface p-5"><SectionLabel>PROCESSING TIMELINE</SectionLabel>{stages.map((s,i) => <div className="flex gap-4 border-b border-[#b7ced0] py-4" key={s}><span className={`flex h-7 w-7 shrink-0 items-center justify-center border font-mono text-[10px] ${stage > i ? 'border-[#49a6ae] bg-[#c6fcff] text-[#0f4c52]' : stage === i && stage > 0 ? 'border-[#d08a36] text-[#d08a36]' : 'border-[#b7ced0] text-[#587579]'}`}>{stage > i ? <Check size={14} /> : `0${i + 1}`}</span><span><span className="block text-[13px] font-semibold text-[#0f4c52]">{s}</span><span className="font-mono text-[10px] text-[#587579]">{stage > i ? 'COMPLETE / VERIFIED' : stage === i && stage > 0 ? 'PROCESSING...' : 'QUEUED'}</span></span></div>)}{stage === stages.length && <div className="mt-5 border border-[#92e6ec] bg-[#c6fcff] p-4 text-[12px] font-semibold text-[#0f4c52]" data-testid="status-decryption-success">DECRYPTION COMPLETE / DOCUMENT ACCESS GRANTED</div>}</div></div></Shell>; }

function RecipientHistory() { return <Shell role="recipient" section="History"><PageHeader eyebrow="RECIPIENT / ACCESS HISTORY" title="Access history" description="A local record of document access and verification events bound to your identity." /><div className="surface">{[['26 SEP 2026 14:32:54','DOC-2026-001','Decryption complete','VERIFIED'],['26 SEP 2026 14:32:02','DOC-2026-001','Envelope received','SEALED'],['18 SEP 2026 09:11:08','DOC-2026-003','Document accessed','VERIFIED']].map((r) => <div className="data-row grid grid-cols-[1.2fr_1fr_1.4fr_100px] gap-4 px-5 py-4 text-[12px] max-md:grid-cols-[1fr_1fr_100px]" key={r[0]}><span className="font-mono text-[10px] text-[#587579]">{r[0]}</span><span className="font-mono text-[#0f4c52]">{r[1]}</span><span className="font-semibold text-[#0f4c52]">{r[2]}</span><span className="text-right font-mono text-[10px]">{r[3]}</span></div>)}</div></Shell>; }

function LedgerTable({ compact = false }: { compact?: boolean }) { const rows = [{ n:'185', t:'2026-09-26 14:32:09', prev:'000000…B91A', hash:ledgerTampered ? 'MISMATCH' : 'B8A1C4…A102', event:'LEDGER_VERIFY' }, { n:'184', t:'2026-09-26 14:32:08', prev:'77D02E…91F0', hash:'C4E988…8F3A', event:eventId }, { n:'183', t:'2026-09-26 11:08:42', prev:'A11BB2…D02E', hash:'77D02E…91F0', event:'DEC-000183' }]; const [drawer, setDrawer] = useState<string | null>(null); return <><div className="surface overflow-hidden"><div className="grid grid-cols-[55px_1.2fr_1fr_1fr_100px] border-b border-[#b7ced0] bg-[#f1f8f8] px-4 py-3 text-[9px] font-bold uppercase tracking-[.11em] text-[#587579]"><span>Block</span><span>Timestamp</span><span>Previous hash</span><span>Block hash</span><span>Event</span></div>{rows.slice(0, compact ? 3 : rows.length).map((r) => <button onClick={() => setDrawer(r.n)} className="data-row grid w-full grid-cols-[55px_1.2fr_1fr_1fr_100px] items-center gap-2 px-4 py-4 text-left max-md:grid-cols-[55px_1fr_1fr_80px]" key={r.n} data-testid={`button-ledger-block-${r.n}`}><span className="font-mono text-[12px] font-bold text-[#0f4c52]">{r.n}</span><span className="font-mono text-[10px] text-[#587579]">{r.t}</span><span className="font-mono text-[10px] text-[#587579] max-md:hidden">{r.prev}</span><span className={`font-mono text-[10px] ${r.hash === 'MISMATCH' ? 'text-[#8e2929]' : 'text-[#0f4c52]'}`}>{r.hash}</span><span className="truncate font-mono text-[9px] text-[#587579]">{r.event}</span></button>)}</div>{drawer && <TechnicalDrawer title={`LEDGER BLOCK ${drawer}`} onClose={() => setDrawer(null)}><HashDisplay label="Block hash" value={drawer === '184' ? 'C4E98811A0F27F83A2B9' : drawer === '185' ? (ledgerTampered ? 'MISMATCH / 5C02' : 'B8A1C4D2907EA102') : '77D02E1191BBBD02E'} /><div className="mt-4 space-y-0"><StatusRow label="Previous hash" value={drawer === '185' && ledgerTampered ? 'MISMATCH' : 'MATCH'} state={drawer === '185' && ledgerTampered ? 'failure' : 'verified'} /><StatusRow label="Event signature" value="ML-DSA VALID" /><StatusRow label="Chain position" value={`BLOCK ${drawer}`} /></div></TechnicalDrawer>}</>; }

function TechnicalDrawer({ title, onClose, children }: { title: string; onClose: () => void; children: React.ReactNode }) { return <><div className="scrim" onClick={onClose} /><aside className="drawer p-5" data-testid="technical-drawer"><div className="mb-7 flex items-start justify-between border-b border-[#b7ced0] pb-4"><div><div className="eyebrow mb-2">TECHNICAL DETAIL</div><h2 className="font-display text-2xl font-semibold text-[#0f4c52]">{title}</h2></div><button className="btn-quiet !p-2" onClick={onClose} data-testid="button-close-drawer"><X size={15} /></button></div>{children}</aside></>; }

function AdminEvents() { return <Shell role="admin" section="Events"><PageHeader eyebrow="ADMIN / DECRYPTION REGISTER" title="Decryption events" description="Dense event register for all recipient-side access attempts. Select an event for its technical detail." /><div className="surface overflow-hidden"><div className="grid grid-cols-[1fr_1fr_1.1fr_1fr_110px] border-b border-[#b7ced0] bg-[#f1f8f8] px-4 py-3 text-[10px] font-bold uppercase tracking-[.12em] text-[#587579] max-md:grid-cols-[1fr_1fr_1fr_90px]"><span>Event ID</span><span>Document</span><span>Recipient / session</span><span>Recorded</span><span>Result</span></div>{[['DEC-000184','DOC-2026-001','REC-003 / 8F3A','26 SEP 14:32','MATCHED'],['DEC-000183','DOC-2026-002','REC-004 / 71C2','26 SEP 11:08','VERIFIED'],['DEC-000182','DOC-2026-003','REC-005 / 09B1','25 SEP 16:44','VERIFIED'],['DEC-000181','DOC-2026-001','REC-003 / 8F3A','25 SEP 09:14','REJECTED']].map((r) => <div className="data-row grid grid-cols-[1fr_1fr_1.1fr_1fr_110px] items-center gap-3 px-4 py-4 text-[11px] max-md:grid-cols-[1fr_1fr_1fr_90px]" key={r[0]}><span className="font-mono font-bold text-[#0f4c52]">{r[0]}</span><span className="font-mono text-[#587579]">{r[1]}</span><span className="font-mono text-[#587579]">{r[2]}</span><span className="font-mono text-[10px] text-[#587579]">{r[3]}</span><span className={`font-mono text-[10px] ${r[4] === 'REJECTED' ? 'text-[#8e2929]' : 'text-[#0f4c52]'}`}>{r[4]}</span></div>)}</div></Shell>; }

function AdminPQC() { return <Shell role="admin" section="PQC identity"><PageHeader eyebrow="ADMIN / POST-QUANTUM IDENTITY" title="PQC identity status" description="Operational key material used to sign release and decryption events in the private simulation." /><div className="grid gap-7 md:grid-cols-3">{[['ML-KEM-768','Key encapsulation','ACTIVE','KEM-2A19…7F82'],['ML-DSA-65','Event signature','ACTIVE','DSA-9081…3C4D'],['AES-256-GCM','Content encryption','ACTIVE','GCM-4F12…A8D0']].map((x) => <div className="surface p-5" key={x[0]}><IconBox><KeyRound size={15} /></IconBox><div className="mt-7 font-display text-xl font-semibold text-[#0f4c52]">{x[0]}</div><div className="mt-1 text-[12px] text-[#587579]">{x[1]}</div><div className="mt-7 border-t border-[#b7ced0] pt-4 font-mono text-[10px] text-[#0f4c52]">{x[2]} / {x[3]}</div></div>)}</div></Shell>; }

function AdminLedger() { const [tampered, setTampered] = useState(ledgerTampered); const [verified, setVerified] = useState(false); return <Shell role="admin" section="Private ledger"><PageHeader eyebrow="ADMIN / PRIVATE LEDGER" title="Private ledger" description="Technical chain view for release, access, and verification events. Block inspection opens a detail drawer." actions={<div className="flex gap-2"><button className="btn-quiet flex items-center gap-2" onClick={() => { setVerified(true); setTimeout(() => setVerified(false), 2200); }} data-testid="button-verify-ledger"><ClipboardCheck size={14} /> Verify chain</button><button className="btn-danger flex items-center gap-2" onClick={() => { ledgerTampered = true; setTampered(true); }} data-testid="button-tamper-ledger"><CircleAlert size={14} /> Simulate tamper</button></div>} />{verified && <div className="mb-5 border border-[#92e6ec] bg-[#c6fcff] p-4 font-mono text-[11px] text-[#0f4c52]" data-testid="status-ledger-verified">CHAIN VERIFICATION COMPLETE / {tampered ? 'MISMATCH DETECTED AT BLOCK 185' : 'ALL 185 BLOCKS INTACT'}</div>}{tampered && <div className="mb-5 flex items-center justify-between border border-[#d89b9b] bg-[#f6dfdf] p-4 text-[12px] text-[#8e2929]" data-testid="status-ledger-tampered"><span><strong>LEDGER TAMPER STATE</strong> — block 184 hash mismatch; block 185 previous-hash mismatch.</span><button className="btn-quiet !border-[#d89b9b] !text-[#8e2929]" onClick={() => { ledgerTampered = false; setTampered(false); }} data-testid="button-restore-ledger"><RotateCcw size={13} className="mr-2 inline" /> Restore valid state</button></div>}<LedgerTable /></Shell>; }

function AdminHealth() { return <Shell role="admin" section="Health"><PageHeader eyebrow="ADMIN / SYSTEM HEALTH" title="System health" description="Local service abstractions and isolated node conditions. Future FastAPI adapters can replace these deterministic checks." /><div className="surface p-5">{[['API adapter','READY','Mock service boundary'],['Key vault','ONLINE','PQC identity material loaded'],['Private ledger','INTACT','185 blocks / 0 unresolved'],['Air-gapped relay','SEALED','Outbound policy enforced'],['Forensic matcher','READY','Watermark index loaded']].map((x) => <StatusRow key={x[0]} label={x[0]} value={x[1]} detail={x[2]} />)}</div></Shell>; }

function EvidenceChain({ onNode }: { onNode: (label: string) => void }) { const nodes = ['DOCUMENT','RECIPIENT','SESSION','WATERMARK','SIGNATURE','LEDGER BLOCK']; return <div className="surface p-5"><SectionLabel>PROVENANCE CHAIN <span className="ml-2 font-mono text-[10px] text-[#49a6ae]">CLICK NODE FOR TECHNICAL DETAIL</span></SectionLabel><div className="flex items-center justify-between gap-1 overflow-x-auto pb-2">{nodes.map((n,i) => <div className="flex min-w-max flex-1 items-center" key={n}><button onClick={() => onNode(n)} className="group flex flex-col items-center gap-2" data-testid={`button-evidence-node-${n.toLowerCase().replace(' ','-')}`}><span className="flex h-9 w-9 items-center justify-center border border-[#49a6ae] bg-[#c6fcff] text-[#0f4c52] group-hover:bg-[#92e6ec]">{i === 0 ? <FileText size={14} /> : i === 1 ? <UserRound size={14} /> : i === 2 ? <Zap size={14} /> : i === 3 ? <Fingerprint size={14} /> : i === 4 ? <ShieldCheck size={14} /> : <Database size={14} />}</span><span className="font-mono text-[9px] text-[#0f4c52]">{n}</span></button>{i < nodes.length - 1 && <span className="chain-line mx-2 min-w-3" />}</div>)}</div></div>; }

function InvestigatorNew() { const [uploaded, setUploaded] = useState(false); const [started, setStarted] = useState(false); const [failure, setFailure] = useState(''); return <Shell role="investigator" section="Investigations" detail="NEW"><PageHeader eyebrow="INVESTIGATOR / INTAKE" title="New investigation" description="Load a suspected leaked artifact into the air-gapped forensic workbench. Upload is simulated and does not transmit data." /><div className="grid gap-7 lg:grid-cols-[1.1fr_.9fr]"><div className="surface p-6"><SectionLabel>LEAKED ARTIFACT</SectionLabel><button onClick={() => { setUploaded(true); setFailure(''); }} className="flex min-h-[235px] w-full flex-col items-center justify-center border-2 border-dashed border-[#92e6ec] bg-[#f1f8f8] p-8 text-center hover:bg-[#eaf4f5]" data-testid="button-upload-evidence"><IconBox>{uploaded ? <Check size={17} /> : <CloudUpload size={17} />}</IconBox><div className="mt-4 font-display text-xl font-semibold text-[#0f4c52]">{uploaded ? 'Leaked_Operations_Report.pdf' : 'Drop leaked PDF here'}</div><div className="mt-2 font-mono text-[10px] text-[#587579]">{uploaded ? 'UPLOAD ACCEPTED / 8.4 MB / SHA-256 PRECALCULATED' : 'PDF ONLY / MAX 50 MB / AIR-GAPPED SIMULATION'}</div></button>{uploaded && <div className="mt-5 flex justify-between border border-[#b7ced0] p-3 font-mono text-[10px] text-[#587579]"><span>SHA-256</span><span className="text-[#0f4c52]">9AA1D3…7F83A2B9</span></div>}</div><div className="surface p-6"><SectionLabel>ANALYSIS PARAMETERS</SectionLabel><StatusRow label="Watermark detector" value="ENABLED" /><StatusRow label="Event matcher" value="ENABLED" /><StatusRow label="ML-DSA verifier" value="ENABLED" /><StatusRow label="Ledger resolver" value="ENABLED" /><button className="btn-primary mt-6 flex w-full items-center justify-center gap-2 disabled:cursor-not-allowed disabled:opacity-50" disabled={!uploaded} onClick={() => { setStarted(true); setFailure(''); }} data-testid="button-start-analysis">{started ? <Check size={14} /> : <ScanSearch size={14} />} {started ? 'Analysis queued' : 'Run forensic analysis'}</button>{started && <Link href="/investigator/investigations/INV-2026-009" className="mt-3 block text-center font-mono text-[10px] text-[#0f4c52] underline" data-testid="link-analysis-case">Open case INV-2026-009</Link>}<div className="mt-7 border-t border-[#b7ced0] pt-4"><div className="eyebrow mb-3">FAULT INJECTION / TEST STATES</div><div className="flex flex-wrap gap-2">{['INVALID UPLOAD','PROCESSING FAILURE','WATERMARK NOT FOUND','SIGNATURE FAILURE'].map((label) => <button className="btn-quiet !px-2 !py-1.5 !text-[10px]" onClick={() => setFailure(label)} key={label} data-testid={`button-failure-${label.toLowerCase().replaceAll(' ','-')}`}>{label}</button>)}</div>{failure && <div className="mt-4 flex items-start gap-2 border border-[#d89b9b] bg-[#f6dfdf] p-3 text-[11px] leading-5 text-[#8e2929]" data-testid="status-forensic-failure"><CircleAlert size={15} className="mt-0.5 shrink-0" />{failure} — simulation halted. Inspect input and retry from a clean worker state.</div>}</div></div></div></Shell>; }

function InvestigatorAnalysis() { const [drawer, setDrawer] = useState<string | null>(null); const [progress, setProgress] = useState(6); const steps = ['Watermark detection','Event match','ML-DSA verification','Document hash match','Ledger verification']; return <Shell role="investigator" section="Investigations" detail="INV-2026-009"><PageHeader eyebrow="INVESTIGATOR / FORENSIC WORKBENCH" title="Investigation analysis" description="Provenance reconstruction for the uploaded leaked artifact. All five verification layers returned a deterministic match." actions={<Link href="/investigator/evidence/INV-2026-009" className="btn-primary flex items-center gap-2" data-testid="button-open-evidence"><PanelRight size={14} /> Open evidence chain</Link>} /><div className="mb-7"><EvidenceChain onNode={setDrawer} /></div><div className="grid gap-6 xl:grid-cols-[.95fr_1.05fr]"><div className="forensic-sheet min-h-[520px] p-7"><div className="relative z-10"><div className="flex items-start justify-between"><div className="eyebrow">LEAKED EVIDENCE / PDF PREVIEW</div><span className="font-mono text-[10px] text-[#587579]">PAGE 01 / 08</span></div><div className="mt-14 border-y border-[#92e6ec] py-7"><FileText className="text-[#49a6ae]" size={30} /><h2 className="mt-5 font-display text-3xl font-semibold tracking-[-.04em] text-[#0f4c52]">Strategic Operations<br />Report</h2><p className="mt-4 max-w-sm text-[12px] leading-6 text-[#587579]">Recovered content fragment. Visible watermark coordinates and formatting fingerprint align with a restricted institutional release.</p></div><div className="mt-12 grid gap-3"><HashDisplay label="Recovered watermark" value={watermark} /><HashDisplay label="Evidence digest" value="9AA1D3C4F6B0…7F83A2B9" /></div></div></div><div className="surface p-5"><SectionLabel right={<span className="font-mono text-[10px] text-[#49a6ae]">LIVE / MATCHED</span>}>CRYPTOGRAPHIC ANALYSIS</SectionLabel><div className="border border-[#92e6ec] bg-[#c6fcff] p-5"><div className="eyebrow text-[#0f4c52]">FORENSIC RESULT</div><h2 className="mt-3 font-display text-[clamp(28px,4vw,42px)] font-semibold leading-[.95] tracking-[-.05em] text-[#0f4c52]" data-testid="text-forensic-result">DECRYPTION EVENT<br />MATCHED</h2><div className="mt-5 font-mono text-[10px] text-[#0f4c52]">CONFIDENCE / 98.7% · EVENT / {eventId}</div></div><div className="mt-5">{steps.map((s,i) => <StatusRow key={s} label={s} value="MATCH" detail={i === 0 ? watermark : i === 1 ? `${eventId} / ${sessionId}` : i === 2 ? 'ML-DSA-65 / VALID' : i === 3 ? 'DOC-2026-001 / MATCH' : 'BLOCK 184 / INTACT'} />)}</div><div className="mt-5 border-t border-[#b7ced0] pt-4"><div className="mb-2 flex justify-between font-mono text-[10px] text-[#587579]"><span>ANALYSIS PIPELINE</span><span>{progress === 100 ? 'COMPLETE' : 'READY'}</span></div><div className="h-1 bg-[#b7ced0]"><div className="h-1 bg-[#49a6ae]" style={{ width: `${progress}%` }} /></div>{progress < 100 && <button className="btn-quiet mt-4 flex items-center gap-2" onClick={() => setProgress(100)} data-testid="button-complete-analysis"><Zap size={13} /> Complete pipeline</button>}</div></div></div>{drawer && <TechnicalDrawer title={drawer} onClose={() => setDrawer(null)}><div className="space-y-0"><StatusRow label="Resolved value" value={drawer === 'DOCUMENT' ? 'DOC-2026-001' : drawer === 'RECIPIENT' ? 'REC-003' : drawer === 'SESSION' ? sessionId : drawer === 'WATERMARK' ? watermark : drawer === 'SIGNATURE' ? 'VALID' : '184 / INTACT'} /><StatusRow label="Resolution source" value="PRIVATE LEDGER" /><StatusRow label="Confidence" value="98.7%" /></div><div className="mt-5"><HashDisplay label="Technical digest" value="C4E98811A0F27F83A2B9" /></div></TechnicalDrawer>}</Shell>; }

function EvidenceDetail() { return <Shell role="investigator" section="Evidence" detail="INV-2026-009"><PageHeader eyebrow="INVESTIGATOR / EVIDENCE CHAIN" title="Evidence chain" description="Technical attribution record linking the recovered PDF to a single release and decryption event." actions={<Link href="/investigator/investigations/INV-2026-009" className="btn-quiet flex items-center gap-2" data-testid="button-back-analysis"><ArrowLeft size={14} /> Back to analysis</Link>} /><EvidenceChain onNode={() => undefined} /><div className="mt-7 grid gap-7 lg:grid-cols-[1.1fr_.9fr]"><div className="surface p-5"><SectionLabel>ATTRIBUTION RECORD</SectionLabel>{[['Document','DOC-2026-001 / Strategic Operations Report'],['Recipient','REC-003 / Ananya Sharma'],['Session',sessionId],['Watermark',watermark],['Decryption event',eventId],['Ledger block','184 / C4E988…8F3A']].map((x) => <div className="data-row flex items-center justify-between gap-4 py-4" key={x[0]}><span className="eyebrow">{x[0]}</span><span className="font-mono text-right text-[11px] text-[#0f4c52]">{x[1]}</span></div>)}</div><div className="surface-deep p-5"><SectionLabel>CHAIN INTEGRITY</SectionLabel><StatusRow label="Document hash" value="MATCH" /><StatusRow label="Watermark" value="MATCH" /><StatusRow label="ML-DSA" value="VALID" /><StatusRow label="Ledger" value="INTACT" /><div className="mt-6"><HashDisplay label="Evidence bundle" value="EVD-2026-009 / SEALED" /></div></div></div></Shell>; }

function InvestigatorReports() { return <Shell role="investigator" section="Reports"><PageHeader eyebrow="INVESTIGATOR / REPORTS" title="Investigation reports" description="Completed forensic outputs prepared for institutional review." actions={<Link href="/investigator/investigations/new" className="btn-primary flex items-center gap-2" data-testid="button-new-investigation"><ScanSearch size={14} /> New investigation</Link>} /><div className="surface"><div className="data-row flex items-center justify-between gap-4 p-5"><div className="flex items-center gap-3"><IconBox><FileCheck2 size={15} /></IconBox><span><span className="block font-semibold text-[#0f4c52]">INV-2026-009 / DECRYPTION EVENT MATCHED</span><span className="font-mono text-[10px] text-[#587579]">DOC-2026-001 · REC-003 · 26 SEP 2026</span></span></div><Link href="/investigator/evidence/INV-2026-009" className="btn-quiet" data-testid="button-open-report">View report</Link></div></div></Shell>; }

function LoginEntry() { const [location] = useLocation(); const segment = location.split('/')[2]; const role = (['authority', 'recipient', 'admin', 'investigator'].includes(segment ?? '') ? segment : 'authority') as Role; return <Login role={role} />; }

function Login({ role }: { role: Role }) { const [, setLocation] = useLocation(); const [username, setUsername] = useState(role === 'recipient' ? 'ananya' : role); const [password, setPassword] = useState('demo'); const [error, setError] = useState(''); const meta = roleMeta[role]; const submit = (e: React.FormEvent) => { e.preventDefault(); const valid = password === 'demo' && ((role === 'recipient' && ['ananya','rahul','vikram'].includes(username)) || (role !== 'recipient' && username === role)); if (!valid) { setError('Credential pair not recognized in simulation.'); return; } localStorage.setItem('sdms-role', role); localStorage.setItem('sdms-user', username); setLocation(meta.home); }; return <div className="sdms-shell tech-grid flex min-h-[100dvh] items-center justify-center p-5"><div className="w-full max-w-[920px] border border-[#b7ced0] bg-[#eaf4f5] shadow-[12px_12px_0_#b7ced0]"><div className="grid md:grid-cols-[.9fr_1.1fr]"><div className="surface-deep p-8 md:p-12"><div className="flex items-center gap-3"><span className="flex h-9 w-9 items-center justify-center border border-[#92e6ec] text-[#c6fcff]"><Terminal size={17} /></span><span className="font-display text-2xl font-bold">SDMS<span className="text-[#92e6ec]">/</span></span></div><div className="mt-24 eyebrow text-[#92e6ec]">SECURE DOCUMENT MANAGEMENT SYSTEM</div><h1 className="mt-4 font-display text-4xl font-semibold leading-[.96] tracking-[-.05em] text-[#f1f8f8]">Controlled release.<br />Traceable access.</h1><p className="mt-6 text-[12px] leading-6 text-[#b9d8da]">Phase 1 operations console for institutional document custody, recipient decryption, and forensic attribution.</p><div className="mt-16 font-mono text-[10px] text-[#92e6ec]">AIR-GAPPED SIMULATION / NODE 01</div></div><form onSubmit={submit} className="p-8 md:p-12"><div className="eyebrow mb-3">{meta.label} / AUTHENTICATION</div><h2 className="font-display text-3xl font-semibold tracking-[-.04em] text-[#0f4c52]">Enter operations console</h2><p className="mt-3 text-[12px] leading-5 text-[#587579]">Use the deterministic demo credential for this role.</p><div className="mt-9 space-y-5"><label className="block"><span className="eyebrow mb-2 block">Identity handle</span><input value={username} onChange={(e) => setUsername(e.target.value)} className="w-full border border-[#b7ced0] bg-[#f1f8f8] px-3 py-3 text-[13px] text-[#0f4c52]" data-testid="input-username" autoComplete="username" /></label><label className="block"><span className="eyebrow mb-2 block">Passphrase</span><input type="password" value={password} onChange={(e) => setPassword(e.target.value)} className="w-full border border-[#b7ced0] bg-[#f1f8f8] px-3 py-3 text-[13px] text-[#0f4c52]" data-testid="input-password" autoComplete="current-password" /></label></div>{error && <div className="mt-4 flex gap-2 border border-[#d89b9b] bg-[#f6dfdf] p-3 text-[12px] text-[#8e2929]" data-testid="status-login-error"><CircleAlert size={15} /> {error}</div>}<button className="btn-primary mt-7 flex w-full items-center justify-center gap-2" type="submit" data-testid="button-login"><LockKeyhole size={14} /> Authenticate as {meta.label}</button><div className="mt-6 border-t border-[#b7ced0] pt-4 font-mono text-[10px] text-[#587579]">DEMO / {role === 'recipient' ? 'ananya | rahul | vikram' : role} + demo</div></form></div></div></div>; }

function NotFound() { return <div className="sdms-shell flex min-h-[100dvh] items-center justify-center"><div className="surface p-10 text-center"><div className="eyebrow">404 / UNRESOLVED ROUTE</div><h1 className="title-display mt-3">Record not found</h1><Link href="/login/authority" className="btn-primary mt-6 inline-flex" data-testid="link-return-login">Return to entry</Link></div></div>; }

function Router() {
  return <Switch>
    <Route path="/" component={LoginEntry} />
    <Route path="/login/:role" component={LoginEntry} />
    <Route path="/authority/dashboard"><Dashboard role="authority" /></Route><Route path="/authority/documents" component={AuthorityDocuments} /><Route path="/authority/distributions/new" component={NewDistribution} /><Route path="/authority/distributions/:id" component={DistributionRecord} /><Route path="/authority/history" component={AuthorityHistory} />
    <Route path="/recipient/dashboard"><Dashboard role="recipient" /></Route><Route path="/recipient/documents" component={RecipientDocuments} /><Route path="/recipient/documents/:id" component={RecipientDocument} /><Route path="/recipient/decrypt/:id" component={DecryptPage} /><Route path="/recipient/history" component={RecipientHistory} />
    <Route path="/admin/dashboard"><Dashboard role="admin" /></Route><Route path="/admin/events" component={AdminEvents} /><Route path="/admin/pqc" component={AdminPQC} /><Route path="/admin/ledger" component={AdminLedger} /><Route path="/admin/health" component={AdminHealth} />
    <Route path="/investigator/dashboard"><Dashboard role="investigator" /></Route><Route path="/investigator/investigations/new" component={InvestigatorNew} /><Route path="/investigator/investigations/:id" component={InvestigatorAnalysis} /><Route path="/investigator/evidence/:id" component={EvidenceDetail} /><Route path="/investigator/reports" component={InvestigatorReports} />
    <Route component={NotFound} />
  </Switch>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><ErrorBoundary resetKey={location.pathname}><Router /></ErrorBoundary></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;